\label{thm:planar-convergence}
Under these assumptions, every classical DFP sequence with positive
step lengths satisfying \eqref{eq:armijo}--\eqref{eq:weak-curvature}
either reaches the unique minimizer $x_*$ in finitely many iterations
or satisfies $x_k\to x_*$ and $\|\nabla f(x_k)\|\to0$.

\label{lem:polar-dfp}
Fix $k\ge0$. Suppose that $\rho_k,\rho_{k+1},\zeta_k,\zeta_{k+1}>0$,
$Z_k\succ0$, $(Z_k)_{12}>0$, and $0<\delta_k<\pi$.
Then the following statements hold.
\begin{itemize}
\item[\textup{i)}] There exists a positive step length $\alpha_k$ satisfying
$s_k=-\alpha_kH_kg_k$ if and only if
\begin{equation}\label{eq:fixed-step}
 r_k=\cos\delta_k+h_k\sin\delta_k.
\end{equation}
In this case, the step length $\alpha_k$ is unique and is given by \eqref{eq:fixed-realization}.
\item[\textup{ii)}] If \eqref{eq:fixed-step} and $p_k^Tq_k>0$ hold,
then $s_k^Ty_k>0$ and the DFP update \eqref{eq:dfp-update} is equivalent to
\begin{equation}\label{eq:fixed-update}
 Z_{k+1}=R(\delta_k)^T
 \left[\left(I-\frac{q_kp_k^T}{p_k^Tq_k}\right)Z_k
       \left(I-\frac{p_kq_k^T}{p_k^Tq_k}\right)
       +\frac{q_kq_k^T}{p_k^Tq_k}\right]R(\delta_k)\succ0.
\end{equation}
\end{itemize}

\label{lem:fixed-single-limit}
Fix $X\succ0$ with $X_{12}>0$ and put $Z=S_\tau^{-1}XS_\tau^{-1}$.
Suppose $\delta=\bar\delta\tau$ with $\bar\delta>0$ fixed and
$\zeta,\zeta_+\to1$ as $\tau\downarrow0$. Then $p^Tq>0$ for all
sufficiently small $\tau>0$, and the update \eqref{eq:fixed-scaled-update} satisfies
\begin{equation}\label{eq:fixed-limiting-map}
 S_\tau Z_+S_\tau\longrightarrow L_{\bar\delta}(X)
 =\begin{pmatrix}
 \gamma&\gamma(\bar h-\bar\delta)\\
 \gamma(\bar h-\bar\delta)&1+\gamma(\bar h-\bar\delta)^2
 \end{pmatrix}.
\end{equation}
The limit is positive definite and has determinant $\gamma$.

\label{lem:fixed-cycle}
The map $\Phi(\tau^2,t,\gamma,u)$ defined in \eqref{eq:fixed-two-step-map}
extends analytically to a neighborhood of $(0,0,\gamma_*,0)$.
For sufficiently small $\tau^2,t\ge0$ in this neighborhood, it satisfies
\begin{align}
 &\|u_+\|_*\le \kappa_1\|u\|_*+\kappa_2(t+\tau^2),
 \label{eq:fixed-transverse}\\
 &\gamma_+=\gamma-\frac43 t(\gamma-\gamma_*)
   +O(t\|u\|_*+t^2+\tau^2),
 \label{eq:fixed-scalar}
\end{align}
for a fixed norm $\|\cdot\|_*$, $0<\kappa_1<1$, and $\kappa_2>0$.
The estimates are uniform on sufficiently small closed neighborhoods
of $\gamma_*$ and $u=0$.
For $\tau>0$ in these neighborhoods, both stages are well defined with
$Z\succ0$, $Z_{12}>0$, and $r,p^Tq>0$.

\label{lem:fixed-continuation}
For sufficiently large $j_0$, the recurrence is well defined for all $k\ge0$
with $Z_k\succ0$, $(Z_k)_{12}>0$, and $r_k,p_k^Tq_k>0$.
For every $j\ge0$,
\begin{equation}\label{eq:fixed-tube}
\begin{gathered}
 \gamma_j-\gamma_*=O(N_j^{-1/3}),\qquad
 X_j-X_{\mathrm E}(\gamma_j)=O(N_j^{-1}),\\
 S_{\tau_j}Z_{2j+1}S_{\tau_j}-X_{\mathrm O}(\gamma_j)
 =O(N_j^{-1}).
\end{gathered}
\end{equation}
The constants in \eqref{eq:fixed-tube} are independent of $j$ and $j_0$
once $j_0$ is sufficiently large.

\label{lem:general-continuation}
For sufficiently large $j_0$, the recurrence is defined for every $k\ge0$,
with $Z_k\succ0$, $(Z_k)_{12}>0$, $r_k>0$, and $p_k^Tq_k>0$.
In a fixed norm $\|\cdot\|_*$ there are constants $\kappa_6,\kappa_8>0$ such that
\begin{equation}\label{eq:general-tube}
 \|u_j\|_*\le \kappa_6N_j^{-1},\qquad
 |\gamma_j-\gamma_*|\le \kappa_8N_j^{1-2\mu}
 =\kappa_8\tau_j^{1-\beta}\qquad(j\ge0).
\end{equation}

\label{lem:planar-degeneration}
Under these assumptions, if $x_k\not\to x_*$, then $\{H_k\}$ is bounded
and, for all sufficiently large $k$,
\begin{equation}\label{eq:planar-degeneration}
0<\lambda_k\le C\|s_{k-1}\|\|s_k\|\longrightarrow0.
\end{equation}
In particular, $\lambda_{\min}(H_k)\to0$.
